//! display/dc/dce/dce_audio.{h,c} + inc/hw/audio.h (Linux 6.18.55), with the
//! `audio_regs`/`audio_shift`/`audio_mask` table of dcn21_resource.c: the
//! Azalia audio endpoints. The table holds 6; `res_cap_rn.num_audio` (4) are
//! created.
//!
//! `dcn21_create_audio` → `dce_audio_create` stores the instance, funcs
//! and register pointers. The ops are ported as the hw sequencer reaches
//! them. The register table is
//! machine-generated by `dcgen.py` from `AUD_COMMON_REG_LIST` /
//! `DCE120_AUD_COMMON_MASK_SH_LIST` (10 regs x 6, 14 shift/mask fields).
#![allow(dead_code)]

use crate::amdgpu_device::amdgpu_device;
use crate::dc_helper::{dm_read_reg, generic_reg_set_ex, get_reg_field_value_ex, reg_set, reg_update,
                       set_reg_field_value_ex};
use crate::regs::*;
use alloc::boxed::Box;

/// Which `audio_funcs` vtable the base points at (the `funcs` table of
/// dce_audio.c).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum audio_funcs {
    dce_audio_funcs,
}

/// `struct audio_funcs` (audio.h), the members ported.
#[derive(Default, Clone, Copy)]
pub struct audio_ops {
    pub hw_init: Option<fn(&amdgpu_device, &dce_audio)>,
}

/// `funcs` (dce_audio.c), as far as ported.
const DCE_AUDIO_FUNCS: audio_ops = audio_ops {
    hw_init: Some(dce_aud_hw_init),
};

impl audio_funcs {
    pub fn ops(self) -> &'static audio_ops {
        match self {
            audio_funcs::dce_audio_funcs => &DCE_AUDIO_FUNCS,
        }
    }
}

/// `struct audio` (inc/hw/audio.h): the audio endpoint base. `ctx` is not
/// stored (see `clock_source`); `enabled` starts false.
#[derive(Default)]
pub struct audio {
    pub funcs: Option<audio_funcs>,
    pub inst: u32,
    pub enabled: bool,
}

/// `struct dce_audio` (dce_audio.h): the concrete endpoint.
#[derive(Default)]
pub struct dce_audio {
    pub base: audio,
    pub regs: Option<&'static dce_audio_registers>,
    pub shifts: Option<&'static dce_audio_shift>,
    pub masks: Option<&'static dce_audio_mask>,
}

/// `dce_audio_create` (dce_audio.c): allocate and fill one endpoint.
pub fn dce_audio_create(
    inst: u32,
    reg: &'static dce_audio_registers,
    shifts: &'static dce_audio_shift,
    masks: &'static dce_audio_mask,
) -> Box<dce_audio> {
    let mut audio = Box::new(dce_audio::default());
    audio.base.inst = inst;
    audio.base.funcs = Some(audio_funcs::dce_audio_funcs);
    audio.regs = Some(reg);
    audio.shifts = Some(shifts);
    audio.masks = Some(masks);
    audio
}

/// `dcn21_create_audio` (dcn21_resource.c).
pub fn dcn21_create_audio(inst: u32) -> Box<dce_audio> {
    dce_audio_create(inst, &AUD_REGS[inst as usize], &AUD_SHIFT, &AUD_MASK)
}

/// `read_indirect_azalia_reg` (dce_audio.c): the Azalia codec is reached
/// through an index/data port pair — write the codec register index to
/// AZALIA_F0_CODEC_ENDPOINT_INDEX, then read AZALIA_F0_CODEC_ENDPOINT_DATA.
pub fn read_indirect_azalia_reg(aud: &dce_audio, adev: &amdgpu_device, reg_index: u32) -> u32 {
    let regs = aud.regs.unwrap();
    let (sh, mk) = (aud.shifts.unwrap(), aud.masks.unwrap());
    generic_reg_set_ex(
        adev,
        regs.AZALIA_F0_CODEC_ENDPOINT_INDEX,
        0,
        &[(sh.AZALIA_ENDPOINT_REG_INDEX, mk.AZALIA_ENDPOINT_REG_INDEX, reg_index)],
    );
    dm_read_reg(adev, regs.AZALIA_F0_CODEC_ENDPOINT_DATA)
}

impl dce_audio {
    /// `audio->funcs`.
    pub fn funcs(&self) -> &'static audio_ops {
        self.base.funcs.expect("audio funcs").ops()
    }

    fn rsm(&self) -> (&'static dce_audio_registers, &'static dce_audio_shift, &'static dce_audio_mask) {
        (self.regs.unwrap(), self.shifts.unwrap(), self.masks.unwrap())
    }
}

/// `write_indirect_azalia_reg` (dce_audio.c).
fn write_indirect_azalia_reg(adev: &amdgpu_device, aud: &dce_audio, reg_index: u32, reg_data: u32) {
    // AZALIA_F0_CODEC_ENDPOINT_INDEX  endpoint index
    reg_set!(adev, aud.rsm(), AZALIA_F0_CODEC_ENDPOINT_INDEX, 0, AZALIA_ENDPOINT_REG_INDEX, reg_index);

    // AZALIA_F0_CODEC_ENDPOINT_DATA  endpoint data
    reg_set!(adev, aud.rsm(), AZALIA_F0_CODEC_ENDPOINT_DATA, 0, AZALIA_ENDPOINT_REG_DATA, reg_data);
}

/// `dce_aud_hw_init` (dce_audio.c): advertise 32, 44.1 and 48 kHz and keep
/// the codec alive. The registers are shared, so only instance 0 programs
/// them; the endpoint register takes its clock gating off around the write.
pub fn dce_aud_hw_init(adev: &amdgpu_device, aud: &dce_audio) {
    if aud.base.inst != 0 {
        return;
    }

    // disable clock gating before write to endpoint register
    let mut value = read_indirect_azalia_reg(aud, adev, ixAZALIA_F0_CODEC_PIN_CONTROL_HOT_PLUG_CONTROL);
    value = set_reg_field_value_ex(value, 1,
        AZALIA_F0_CODEC_PIN_CONTROL_HOT_PLUG_CONTROL__CLOCK_GATING_DISABLE_MASK,
        AZALIA_F0_CODEC_PIN_CONTROL_HOT_PLUG_CONTROL__CLOCK_GATING_DISABLE__SHIFT as u8);
    write_indirect_azalia_reg(adev, aud, ixAZALIA_F0_CODEC_PIN_CONTROL_HOT_PLUG_CONTROL, value);
    reg_update!(adev, aud.rsm(), AZALIA_F0_CODEC_FUNCTION_PARAMETER_SUPPORTED_SIZE_RATES,
        AUDIO_RATE_CAPABILITIES, 0x70);

    // Keep alive bit to verify HW block in BU.
    reg_update!(adev, aud.rsm(), AZALIA_F0_CODEC_FUNCTION_PARAMETER_POWER_STATES, CLKSTOP, 1, EPSS, 1);
    value = set_reg_field_value_ex(value, 0,
        AZALIA_F0_CODEC_PIN_CONTROL_HOT_PLUG_CONTROL__CLOCK_GATING_DISABLE_MASK,
        AZALIA_F0_CODEC_PIN_CONTROL_HOT_PLUG_CONTROL__CLOCK_GATING_DISABLE__SHIFT as u8);
    write_indirect_azalia_reg(adev, aud, ixAZALIA_F0_CODEC_PIN_CONTROL_HOT_PLUG_CONTROL, value);
}

/// `dce_aud_endpoint_valid` (dce_audio.c): an endpoint is valid unless its
/// PORT_CONNECTIVITY reads back as 1 (no port). resource_construct's audio loop
/// stops at the first invalid endpoint.
pub fn dce_aud_endpoint_valid(aud: &dce_audio, adev: &amdgpu_device) -> bool {
    let value = read_indirect_azalia_reg(
        aud,
        adev,
        ixAZALIA_F0_CODEC_PIN_CONTROL_RESPONSE_CONFIGURATION_DEFAULT,
    );
    let port_connectivity = get_reg_field_value_ex(
        value,
        AZALIA_F0_CODEC_PIN_CONTROL_RESPONSE_CONFIGURATION_DEFAULT__PORT_CONNECTIVITY_MASK,
        AZALIA_F0_CODEC_PIN_CONTROL_RESPONSE_CONFIGURATION_DEFAULT__PORT_CONNECTIVITY__SHIFT as u8,
    );
    port_connectivity != 1
}

